            <div className="grid grid-cols-2 gap-3">{(roomEditWallFocus ? [roomEditWallFocus] : wallOptions).map(wall => <label key={wall} className="flex items-center justify-between gap-2 rounded-md border p-2 text-sm capitalize">{wall} wall<input aria-label={`${wall} wall colour`} type="color" value={roomEditDraft.wallColors[wall] || "#f1f5f9"} onChange={e => setRoomEditDraft(v => ({ ...v, wallColors: { ...v.wallColors, [wall]: e.target.value } }))} className="h-9 w-12 cursor-pointer rounded border bg-background p-1" /></label>)}</div>
