            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">{wallOptions.map(wall => { const room = data.rooms.find(item => item.id === roomEditId); const full = room ? (wall === "north" || wall === "south" ? (room.rotation % 180 === 0 ? room.length_ft : room.width_ft) : (room.rotation % 180 === 0 ? room.width_ft : room.length_ft)) : 60; const length = roomEditDraft.wallLengths[wall] ?? full; return <div key={wall} className="space-y-2 rounded-lg border p-3"><div className="flex items-center justify-between gap-2"><label className="flex items-center gap-2 text-sm font-medium capitalize"><input type="checkbox" checked={length > 0} onChange={e => setRoomEditDraft(v => ({ ...v, wallLengths: { ...v.wallLengths, [wall]: e.target.checked ? full : 0 } }))} />{wall} wall</label><span className="text-xs text-muted-foreground">{length} / {full} ft</span></div><input aria-label={`${wall} wall length in feet`} type="range" min="0" max={full} step="0.5" value={length} onChange={e => setRoomEditDraft(v => ({ ...v, wallLengths: { ...v.wallLengths, [wall]: Number(e.target.value) } }))} className="w-full" /><Input aria-label={`${wall} wall length value`} type="number" min="0" step="0.5" max={full} value={length} onChange={e => setRoomEditDraft(v => ({ ...v, wallLengths: { ...v.wallLengths, [wall]: Math.min(full, Math.max(0, Number(e.target.value))) } }))} /></div>; })}</div>
